package net.civeira.phylax.feature.identity.tenantloginprovider.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.feature.identity.tenantloginprovider.domain.TenantLoginProviderProviderTypeOptions;

class ProviderTypeVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property provider type of tenant login provider ")
  void test_provider_type_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> ProviderTypeVO.tryFrom("_GOOGLE_"));
    Assertions.assertEquals(TenantLoginProviderProviderTypeOptions.GOOGLE,
        ProviderTypeVO.tryFrom("GOOGLE").getProviderType());
    Assertions.assertThrows(ConstraintException.class, () -> ProviderTypeVO.tryFrom(null));
    Assertions.assertEquals(TenantLoginProviderProviderTypeOptions.GOOGLE,
        ProviderTypeVO.from(TenantLoginProviderProviderTypeOptions.GOOGLE).getProviderType());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> ProviderTypeVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + TenantLoginProviderProviderTypeOptions.GOOGLE + "]",
        ProviderTypeVO.from(TenantLoginProviderProviderTypeOptions.GOOGLE).toString());
  }
}
